def fetch(url, maxLength=None, startIndex=None, raw=None, **_extra):
    import json, os, datetime, time, base64, hashlib
    from urllib.parse import urlsplit, urlunsplit

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0070000" if __import__("os").path.isdir("./environment_mix/0070000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                dt = datetime.datetime.fromisoformat(s2)
                return dt.replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _today_utc_date():
        return datetime.datetime.utcnow().date()

    def _normalize_url(u):
        if not isinstance(u, str) or not u.strip():
            return None
        try:
            sp = urlsplit(u.strip())
        except Exception:
            return None
        if sp.scheme not in ("http", "https"):
            return None
        if not sp.netloc:
            return None
        scheme = sp.scheme.lower()
        host = sp.hostname.lower() if sp.hostname else ""
        if not host:
            return None
        port = sp.port
        default_port = 80 if scheme == "http" else 443
        netloc = host
        if port and port != default_port:
            netloc = f"{host}:{port}"
        path = sp.path or "/"
        query = sp.query or ""
        fragment = ""  # remove fragment
        return urlunsplit((scheme, netloc, path, query, fragment))

    def _gen_id(prefix):
        return f"{prefix}_{hashlib.sha256((prefix + '|' + str(time.time()) + '|' + os.urandom(8).hex()).encode('utf-8')).hexdigest()[:24]}"

    def _select_output(req, http_responses, extractions):
        # returns (output_string, approx_bytes)
        if req.get("raw") is True:
            hrid = req.get("http_response_id")
            if not hrid:
                return None, 0
            hr = next((r for r in http_responses if r.get("id") == hrid), None)
            if not hr:
                return None, 0
            bs = hr.get("body_storage")
            if bs == "inline_text":
                out = hr.get("body_text") or ""
                return out, int(hr.get("body_bytes") or len(out.encode("utf-8", "ignore")))
            if bs == "inline_base64":
                b64 = hr.get("body_base64") or ""
                try:
                    raw_bytes = base64.b64decode(b64.encode("ascii"), validate=False)
                    out = raw_bytes.decode("utf-8", "replace")
                except Exception:
                    out = ""
                return out, int(hr.get("body_bytes") or len(out.encode("utf-8", "ignore")))
            if bs == "object_store_ref":
                # offline datastore: cannot dereference; return empty but count bytes as stored size
                return "", int(hr.get("body_bytes") or 0)
            if bs == "omitted":
                return "", int(hr.get("body_bytes") or 0)
            return "", int(hr.get("body_bytes") or 0)
        else:
            exid = req.get("extraction_id")
            if not exid:
                return None, 0
            ex = next((e for e in extractions if e.get("id") == exid), None)
            if not ex:
                return None, 0
            out = ex.get("markdown") or ""
            return out, int(len(out.encode("utf-8", "ignore")))

    def _slice(s, start, maxlen):
        if start < 0:
            start = 0
        if start >= len(s):
            return ""
        end = start + maxlen
        return s[start:end]

    # Load collections
    api_keys = _load("api_keys.json")
    fetch_requests = _load("fetch_requests.json")
    http_responses = _load("http_responses.json")
    extractions = _load("extractions.json")
    extraction_images = _load("extraction_images.json")

    # Prepare request log collection (not in schema; only if present)
    request_logs_name = None
    for candidate in ("request_logs.json", "api_request_logs.json", "audit_logs.json", "usage_logs.json"):
        if os.path.exists(os.path.join(_DB, candidate)):
            request_logs_name = candidate
            break
    request_logs = _load(request_logs_name) if request_logs_name else None

    t0 = time.time()
    used_api_key_id = None
    status_for_log = "error"
    bytes_out_for_log = 0

    def _log_and_return(payload):
        nonlocal status_for_log, bytes_out_for_log
        if request_logs_name is not None and isinstance(request_logs, list):
            dt = _now()
            latency_ms = int((time.time() - t0) * 1000)
            request_logs.append({
                "id": _gen_id("reqlog"),
                "endpoint": "fetch",
                "api_key_id": used_api_key_id,
                "status": status_for_log,
                "timestamp": dt,
                "latency_ms": latency_ms,
                "bytes": bytes_out_for_log
            })
            _save(request_logs_name, request_logs)
        return payload

    # Validate inputs
    if not isinstance(url, str) or not url.strip():
        status_for_log = "validation_error"
        return _log_and_return(_err("VALIDATION_ERROR", "url is required and must be a non-empty string", field="url"))
    url_norm = _normalize_url(url)
    if not url_norm:
        status_for_log = "validation_error"
        return _log_and_return(_err("VALIDATION_ERROR", "url must be a valid absolute http(s) URI", field="url"))

    if maxLength is None:
        maxLength = 20000
    if startIndex is None:
        startIndex = 0
    if raw is None:
        raw = False

    # schema says number for fetch tool, but store as integer semantics
    try:
        max_len_int = int(maxLength)
    except Exception:
        status_for_log = "validation_error"
        return _log_and_return(_err("VALIDATION_ERROR", "maxLength must be a number", field="maxLength"))
    try:
        start_idx_int = int(startIndex)
    except Exception:
        status_for_log = "validation_error"
        return _log_and_return(_err("VALIDATION_ERROR", "startIndex must be a number", field="startIndex"))
    if max_len_int <= 0 or max_len_int > 1000000:
        status_for_log = "validation_error"
        return _log_and_return(_err("VALIDATION_ERROR", "maxLength must be > 0 and <= 1000000", field="maxLength"))
    if start_idx_int < 0:
        status_for_log = "validation_error"
        return _log_and_return(_err("VALIDATION_ERROR", "startIndex must be >= 0", field="startIndex"))
    if not isinstance(raw, bool):
        status_for_log = "validation_error"
        return _log_and_return(_err("VALIDATION_ERROR", "raw must be boolean", field="raw"))

    # Ambient auth: choose any active key that can serve (has quota remaining)
    # If no keys exist, proceed unauthenticated/internal (api_key_id null) without quota enforcement.
    chosen_key = None
    active_keys = [k for k in api_keys if k.get("status") == "active" and isinstance(k.get("id"), str)]
    if active_keys:
        # enforce quota based on fetch_requests from today for that key
        today = _today_utc_date()
        for k in active_keys:
            kid = k.get("id")
            qreq = k.get("quota_requests_per_day")
            qbytes = k.get("quota_bytes_per_day")
            if not isinstance(qreq, int) or qreq < 0 or not isinstance(qbytes, int) or qbytes < 0:
                continue
            todays = []
            for fr in fetch_requests:
                if fr.get("api_key_id") != kid:
                    continue
                dt = _parse_dt(fr.get("requested_at"))
                if not dt:
                    continue
                if dt.date() == today:
                    todays.append(fr)
            if len(todays) >= qreq:
                continue
            # best-effort bytes: sum returned slice length when succeeded else 0, if stored fields exist
            # We'll approximate by using request's max_length (upper bound) when succeeded, or 0 otherwise.
            bytes_used = 0
            for fr in todays:
                if fr.get("status") != "succeeded":
                    continue
                # approximate by min(max_length, content length) not easily known; use max_length as upper bound
                ml = fr.get("max_length")
                if isinstance(ml, int) and ml > 0:
                    bytes_used += ml
            if bytes_used >= qbytes:
                continue
            chosen_key = k
            break
        if chosen_key is None:
            used_api_key_id = None
            status_for_log = "quota_exceeded"
            return _log_and_return(_err("QUOTA_EXCEEDED", "No active API key has remaining daily quota for this operation"))
    used_api_key_id = chosen_key.get("id") if chosen_key else None

    # Create fetch_request row (queued initially)
    now = _now()
    req_id = _gen_id("fetchreq")
    cache_key = hashlib.sha256((url_norm + "|raw=" + ("1" if raw else "0")).encode("utf-8")).hexdigest()
    req_row = {
        "id": req_id,
        "api_key_id": used_api_key_id,
        "url": url,
        "url_normalized": url_norm,
        "max_length": max_len_int,
        "start_index": start_idx_int,
        "raw": raw,
        "status": "queued",
        "error_code": None,
        "error_message": None,
        "cache_key": cache_key,
        "cache_hit": False,
        "http_response_id": None,
        "extraction_id": None,
        "requested_at": now,
        "completed_at": None,
        "created_at": now,
        "updated_at": now
    }
    fetch_requests.append(req_row)

    # Transition queued -> fetching
    req_row["status"] = "fetching"
    req_row["updated_at"] = _now()

    # "Fetch" behavior offline: reuse a stored http_response for same cache_key (most recent), else fail.
    matching_resps = [r for r in http_responses if r.get("cache_key") == cache_key]
    # pick most recent fetched_at
    def _fetched_sort_key(r):
        dt = _parse_dt(r.get("fetched_at"))
        return dt or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
    matching_resps.sort(key=_fetched_sort_key, reverse=True)
    hr = matching_resps[0] if matching_resps else None

    if hr is None:
        # cannot perform network; mark failed
        req_row["status"] = "failed"
        req_row["error_code"] = "network_unavailable"
        req_row["error_message"] = "Offline datastore has no cached HTTP response for this URL/cache_key."
        req_row["completed_at"] = _now()
        req_row["updated_at"] = req_row["completed_at"]
        _save("fetch_requests.json", fetch_requests)
        status_for_log = "failed"
        return _log_and_return({
            "fetchRequest": req_row
        })

    # Use cached response
    req_row["cache_hit"] = True
    req_row["http_response_id"] = hr.get("id")
    req_row["updated_at"] = _now()

    # Policy: non-2xx treated as error
    sc = hr.get("status_code")
    if not isinstance(sc, int) or sc < 100 or sc > 599:
        req_row["status"] = "failed"
        req_row["error_code"] = "http_error"
        req_row["error_message"] = "Invalid stored HTTP status_code."
        req_row["completed_at"] = _now()
        req_row["updated_at"] = req_row["completed_at"]
        _save("fetch_requests.json", fetch_requests)
        status_for_log = "failed"
        return _log_and_return({"fetchRequest": req_row})
    if sc < 200 or sc >= 300:
        req_row["status"] = "failed"
        req_row["error_code"] = "http_error"
        req_row["error_message"] = f"Origin returned HTTP {sc}."
        req_row["completed_at"] = _now()
        req_row["updated_at"] = req_row["completed_at"]
        _save("fetch_requests.json", fetch_requests)
        status_for_log = "failed"
        return _log_and_return({"fetchRequest": req_row})

    # Transition fetching -> processing
    req_row["status"] = "processing"
    req_row["updated_at"] = _now()

    # Ensure extraction if raw=false
    if raw is False:
        # reuse existing extraction by http_response_id (unique constraint)
        ex = next((e for e in extractions if e.get("http_response_id") == hr.get("id")), None)
        if ex is None:
            ex_id = _gen_id("extract")
            ex = {
                "id": ex_id,
                "http_response_id": hr.get("id"),
                "cache_key": hashlib.sha256((url_norm + "|raw=0").encode("utf-8")).hexdigest(),
                "status": "pending",
                "markdown": None,
                "markdown_length": 0,
                "title": None,
                "language": None,
                "error_code": None,
                "error_message": None,
                "created_at": _now(),
                "updated_at": _now()
            }
            extractions.append(ex)

        # Perform offline "extraction": derive markdown from stored body text (best effort)
        if ex.get("status") == "pending":
            out_text = ""
            bs = hr.get("body_storage")
            if bs == "inline_text":
                out_text = hr.get("body_text") or ""
            elif bs == "inline_base64":
                b64 = hr.get("body_base64") or ""
                try:
                    out_text = base64.b64decode(b64.encode("ascii"), validate=False).decode("utf-8", "replace")
                except Exception:
                    out_text = ""
            elif bs in ("object_store_ref", "omitted"):
                out_text = ""

            # If we have no text at all, fail extraction
            if out_text == "" and int(hr.get("body_bytes") or 0) > 0:
                ex["status"] = "failed"
                ex["error_code"] = "extraction_failed"
                ex["error_message"] = "Body not available inline for extraction."
                ex["updated_at"] = _now()
            else:
                # naive markdown: treat as plain text
                md = out_text
                ex["markdown"] = md
                ex["markdown_length"] = len(md)
                ex["status"] = "succeeded"
                ex["error_code"] = None
                ex["error_message"] = None
                ex["updated_at"] = _now()

                # Discover images: deterministic ordering. Best-effort: parse <img src="..."> occurrences.
                # Only for html-ish content.
                ctype = (hr.get("content_type") or "").lower()
                if ("html" in ctype) and md:
                    import re
                    from urllib.parse import urljoin
                    img_urls = []
                    for m in re.finditer(r'<img\b[^>]*\bsrc\s*=\s*["\']([^"\']+)["\']', md, flags=re.IGNORECASE):
                        img_urls.append(m.group(1))
                    abs_urls = []
                    base = hr.get("url_final") or url_norm
                    for iu in img_urls:
                        try:
                            abs_urls.append(urljoin(base, iu))
                        except Exception:
                            continue
                    # de-dupe preserving order
                    seen = set()
                    ordered = []
                    for au in abs_urls:
                        if au in seen:
                            continue
                        seen.add(au)
                        ordered.append(au)
                    # Upsert positions for this extraction deterministically
                    existing = [im for im in extraction_images if im.get("extraction_id") == ex.get("id")]
                    # remove any existing to avoid uniqueness issues and to keep deterministic set
                    if existing:
                        existing_ids = set(im.get("id") for im in existing)
                        extraction_images = [im for im in extraction_images if im.get("id") not in existing_ids]
                    tstamp = _now()
                    for i, au in enumerate(ordered):
                        extraction_images.append({
                            "id": _gen_id("eximg"),
                            "extraction_id": ex.get("id"),
                            "position": i,
                            "image_url": au,
                            "alt_text": None,
                            "created_at": tstamp,
                            "updated_at": tstamp
                        })

        if ex.get("status") != "succeeded":
            req_row["status"] = "failed"
            req_row["error_code"] = ex.get("error_code") or "extraction_failed"
            req_row["error_message"] = ex.get("error_message") or "Extraction failed."
            req_row["extraction_id"] = ex.get("id")
            req_row["completed_at"] = _now()
            req_row["updated_at"] = req_row["completed_at"]
            # persist extraction changes and images
            _save("extractions.json", extractions)
            _save("extraction_images.json", extraction_images)
            _save("fetch_requests.json", fetch_requests)
            status_for_log = "failed"
            return _log_and_return({"fetchRequest": req_row})

        req_row["extraction_id"] = ex.get("id")
        # persist extraction + images
        _save("extractions.json", extractions)
        _save("extraction_images.json", extraction_images)

    # Transition processing -> succeeded
    req_row["status"] = "succeeded"
    req_row["error_code"] = None
    req_row["error_message"] = None
    req_row["completed_at"] = _now()
    req_row["updated_at"] = req_row["completed_at"]

    # Compute and return sliced content
    out, approx_bytes = _select_output(req_row, http_responses, extractions)
    if out is None:
        # unexpected missing linkage: treat as failure (no success without effect)
        req_row["status"] = "failed"
        req_row["error_code"] = "missing_content"
        req_row["error_message"] = "Stored content not found for succeeded request."
        req_row["completed_at"] = _now()
        req_row["updated_at"] = req_row["completed_at"]
        _save("fetch_requests.json", fetch_requests)
        status_for_log = "failed"
        return _log_and_return({"fetchRequest": req_row})

    sliced = _slice(out, start_idx_int, max_len_int)
    bytes_out_for_log = len(sliced.encode("utf-8", "ignore"))
    _save("fetch_requests.json", fetch_requests)
    status_for_log = "succeeded"

    # Attach discovered images if available
    images = []
    if raw is False and req_row.get("extraction_id"):
        ims = [im for im in extraction_images if im.get("extraction_id") == req_row.get("extraction_id")]
        ims.sort(key=lambda r: (r.get("position") if isinstance(r.get("position"), int) else 10**9))
        images = [{"position": im.get("position"), "imageUrl": im.get("image_url"), "altText": im.get("alt_text")} for im in ims]

    return _log_and_return({
        "fetchRequest": req_row,
        "content": sliced,
        "images": images,
        "httpResponseId": req_row.get("http_response_id"),
        "extractionId": req_row.get("extraction_id"),
        "cacheHit": req_row.get("cache_hit")
    })

def listFetchRequests(apiKey, status=None, url=None, urlNormalized=None, cacheHit=None, fromRequestedAt=None, toRequestedAt=None, pageToken=None, pageSize=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0070000" if __import__("os").path.isdir("./environment_mix/0070000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                dt = datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
                return dt
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{hashlib.sha256((prefix + '|' + str(time.time()) + '|' + os.urandom(8).hex()).encode('utf-8')).hexdigest()[:24]}"

    t0 = time.time()
    used_api_key_id = None
    status_for_log = "error"

    api_keys = _load("api_keys.json")
    fetch_requests = _load("fetch_requests.json")

    # request log collection if present
    request_logs_name = None
    for candidate in ("request_logs.json", "api_request_logs.json", "audit_logs.json", "usage_logs.json"):
        if os.path.exists(os.path.join(_DB, candidate)):
            request_logs_name = candidate
            break
    request_logs = _load(request_logs_name) if request_logs_name else None

    def _log_and_return(payload):
        if request_logs_name is not None and isinstance(request_logs, list):
            latency_ms = int((time.time() - t0) * 1000)
            request_logs.append({
                "id": _gen_id("reqlog"),
                "endpoint": "listFetchRequests",
                "api_key_id": used_api_key_id,
                "status": status_for_log,
                "timestamp": _now(),
                "latency_ms": latency_ms,
                "bytes": 0
            })
            _save(request_logs_name, request_logs)
        return payload

    # Validate apiKey and authenticate by matching id or key_hash (client-visible)
    if not isinstance(apiKey, str) or not apiKey:
        status_for_log = "validation_error"
        return _log_and_return(_err("VALIDATION_ERROR", "apiKey is required", field="apiKey"))
    k = next((r for r in api_keys if r.get("id") == apiKey or r.get("key_hash") == apiKey), None)
    if not k or k.get("status") != "active":
        status_for_log = "unauthorized"
        return _log_and_return(_err("UNAUTHORIZED", "Invalid or inactive apiKey"))
    used_api_key_id = k.get("id")

    allowed_status = {"queued", "fetching", "processing", "succeeded", "failed"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            status_for_log = "validation_error"
            return _log_and_return(_err("VALIDATION_ERROR", "Invalid status filter", field="status"))
    if url is not None and not isinstance(url, str):
        status_for_log = "validation_error"
        return _log_and_return(_err("VALIDATION_ERROR", "url must be a string", field="url"))
    if urlNormalized is not None and not isinstance(urlNormalized, str):
        status_for_log = "validation_error"
        return _log_and_return(_err("VALIDATION_ERROR", "urlNormalized must be a string", field="urlNormalized"))
    if cacheHit is not None and not isinstance(cacheHit, bool):
        status_for_log = "validation_error"
        return _log_and_return(_err("VALIDATION_ERROR", "cacheHit must be boolean", field="cacheHit"))

    if pageSize is None:
        pageSize = 50
    if not isinstance(pageSize, int) or pageSize < 1 or pageSize > 200:
        status_for_log = "validation_error"
        return _log_and_return(_err("VALIDATION_ERROR", "pageSize must be an integer between 1 and 200", field="pageSize"))

    from_dt = _parse_dt(fromRequestedAt) if fromRequestedAt is not None else None
    if fromRequestedAt is not None and from_dt is None:
        status_for_log = "validation_error"
        return _log_and_return(_err("VALIDATION_ERROR", "fromRequestedAt must be RFC3339 date-time", field="fromRequestedAt"))
    to_dt = _parse_dt(toRequestedAt) if toRequestedAt is not None else None
    if toRequestedAt is not None and to_dt is None:
        status_for_log = "validation_error"
        return _log_and_return(_err("VALIDATION_ERROR", "toRequestedAt must be RFC3339 date-time", field="toRequestedAt"))
    if from_dt and to_dt and to_dt <= from_dt:
        status_for_log = "validation_error"
        return _log_and_return(_err("VALIDATION_ERROR", "toRequestedAt must be > fromRequestedAt", field="toRequestedAt"))

    # Cursor format: "requested_at|id" base64url-ish hex not needed; keep simple delimiter.
    cursor_dt = None
    cursor_id = None
    if pageToken is not None:
        if not isinstance(pageToken, str) or "|" not in pageToken:
            status_for_log = "validation_error"
            return _log_and_return(_err("VALIDATION_ERROR", "Invalid pageToken", field="pageToken"))
        a, b = pageToken.split("|", 1)
        cursor_dt = _parse_dt(a)
        cursor_id = b
        if cursor_dt is None or not cursor_id:
            status_for_log = "validation_error"
            return _log_and_return(_err("VALIDATION_ERROR", "Invalid pageToken", field="pageToken"))

    # Filter to calling API key only (access control)
    rows = [fr for fr in fetch_requests if fr.get("api_key_id") == used_api_key_id]

    if status is not None:
        rows = [fr for fr in rows if fr.get("status") == status]
    if url is not None:
        rows = [fr for fr in rows if fr.get("url") == url]
    if urlNormalized is not None:
        rows = [fr for fr in rows if fr.get("url_normalized") == urlNormalized]
    if cacheHit is not None:
        rows = [fr for fr in rows if fr.get("cache_hit") is cacheHit]
    if from_dt is not None:
        rows = [fr for fr in rows if (_parse_dt(fr.get("requested_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)) >= from_dt]
    if to_dt is not None:
        rows = [fr for fr in rows if (_parse_dt(fr.get("requested_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)) < to_dt]

    # Sort requested_at desc, tie-breaker id desc
    def _k(fr):
        dt = _parse_dt(fr.get("requested_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (dt, fr.get("id") or "")
    rows.sort(key=_k, reverse=True)

    # Apply cursor: return items strictly after the cursor in this ordering
    if cursor_dt is not None:
        filtered = []
        for fr in rows:
            dt = _parse_dt(fr.get("requested_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            fid = fr.get("id") or ""
            if dt < cursor_dt:
                filtered.append(fr)
            elif dt == cursor_dt and fid < cursor_id:
                filtered.append(fr)
        rows = filtered

    total = len(rows)
    page = rows[:pageSize]
    has_more = total > pageSize
    next_cursor = None
    if has_more and page:
        last = page[-1]
        next_cursor = f"{last.get('requested_at')}|{last.get('id')}"

    status_for_log = "succeeded"
    return _log_and_return({
        "fetchRequests": page,
        "total": total,
        "hasMore": has_more,
        "nextPageToken": next_cursor
    })

