    log_row["error_message"] = None
    log_row["completed_at"] = now
    log_row["updated_at"] = now
    fr.append(log_row)
    _save("fetch_requests.json", fr)

    return {
        "api_keys": [_public(r) for r in page],
        "page": {"total": total, "has_more": has_more, "next_page_token": next_token, "page_size": pageSize},
        "request": {"api_key_id": caller.get("id"), "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)},
    }

def getCaller(apiKey, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0070000" if __import__("os").path.isdir("./environment_mix/0070000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _parse_iso_z(ts):
        if not isinstance(ts, str) or not ts:
            return None
        s = ts.strip()
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                if "." in s2:
                    s2 = s2.split(".", 1)[0]
                return datetime.datetime.fromisoformat(s2)
            if "." in s:
                s = s.split(".", 1)[0]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _day_bounds_utc(dt):
        start = dt.replace(hour=0, minute=0, second=0, microsecond=0)
        end = start + datetime.timedelta(days=1)
        return start, end

    def _normalize_key_candidate(v):
        if not isinstance(v, str):
            return None
        v = v.strip()
        return v if v else None

    def _resolve_api_key(apiKey_value, api_keys_rows):
        k = _normalize_key_candidate(apiKey_value)
        if not k or not isinstance(api_keys_rows, list):
            return None
        # Authenticate against client-visible value or id ONLY.
        # In this datastore, callers often pass the api_keys.id as apiKey.
        for r in api_keys_rows:
            if isinstance(r, dict) and r.get("id") == k:
                return r
        # Some stores may also include a plaintext token field; accept if present (not specified but safe).
        for r in api_keys_rows:
            if isinstance(r, dict) and r.get("key") == k:
                return r
        return None

    def _log_call(fetch_requests_rows, api_key_id, status, error_code=None, error_message=None):
        # Use deterministic-ish id to avoid secrets import; sufficient for local datastore.
        req_id = "fch_req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
        row = {
            "id": req_id,
            "api_key_id": api_key_id,
            "url": "internal://getCaller",
            "url_normalized": "internal://getcaller",
            "max_length": 1,
            "start_index": 0,
            "raw": True,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "cache_key": "internal://getcaller",
            "cache_hit": False,
            "http_response_id": None,
            "extraction_id": None,
            "requested_at": now,
            "completed_at": now if status in ("succeeded", "failed") else None,
            "created_at": now,
            "updated_at": now,
        }
        if isinstance(fetch_requests_rows, list):
            fetch_requests_rows.append(row)
        return row

    # Validate inputs first
    if not isinstance(apiKey, str) or not apiKey.strip():
        # still log (unauthenticated/internal calls are allowed in schema but this endpoint requires apiKey)
        fetch_requests_rows = _load("fetch_requests.json")
        _log_call(fetch_requests_rows, None, "failed", error_code="validation_error", error_message="apiKey must be a non-empty string")
        _save("fetch_requests.json", fetch_requests_rows)
        return _err("VALIDATION_ERROR", "apiKey must be a non-empty string", field="apiKey")

    api_keys_rows = _load("api_keys.json")
    fetch_requests_rows = _load("fetch_requests.json")

    key_row = _resolve_api_key(apiKey, api_keys_rows)
    if not isinstance(key_row, dict):
        _log_call(fetch_requests_rows, None, "failed", error_code="unauthorized", error_message="Invalid API key")
        _save("fetch_requests.json", fetch_requests_rows)
        return _err("UNAUTHORIZED", "Invalid API key")

    if key_row.get("status") != "active":
        _log_call(fetch_requests_rows, key_row.get("id"), "failed", error_code="unauthorized", error_message="API key is revoked")
        _save("fetch_requests.json", fetch_requests_rows)
        return _err("UNAUTHORIZED", "API key is revoked")

    # Best-effort usage: count today's fetch_requests by api_key_id; bytes approximated from stored bodies/extractions if available.
    now_parsed = _parse_iso_z(now) or now_dt
    day_start, day_end = _day_bounds_utc(now_parsed)

    todays = []
    if isinstance(fetch_requests_rows, list):
        for r in fetch_requests_rows:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != key_row.get("id"):
                continue
            ra = _parse_iso_z(r.get("requested_at"))
            if ra is None:
                continue
            if day_start <= ra < day_end:
                todays.append(r)

    requests_used = len(todays)

    # Approx bytes: sum of body_bytes when raw=true & http_response_id exists; else markdown_length when raw=false & extraction_id exists.
    http_rows = _load("http_responses.json")
    ext_rows = _load("extractions.json")
    http_by_id = {}
    if isinstance(http_rows, list):
        for hr in http_rows:
            if isinstance(hr, dict) and isinstance(hr.get("id"), str):
                http_by_id[hr["id"]] = hr
    ext_by_id = {}
    if isinstance(ext_rows, list):
        for er in ext_rows:
            if isinstance(er, dict) and isinstance(er.get("id"), str):
                ext_by_id[er["id"]] = er

    bytes_used = 0
    for r in todays:
        raw = bool(r.get("raw"))
        if raw:
            hid = r.get("http_response_id")
            hr = http_by_id.get(hid) if isinstance(hid, str) else None
            if isinstance(hr, dict):
                bb = hr.get("body_bytes")
                if isinstance(bb, int) and bb >= 0:
                    bytes_used += bb
        else:
            eid = r.get("extraction_id")
            er = ext_by_id.get(eid) if isinstance(eid, str) else None
            if isinstance(er, dict):
                ml = er.get("markdown_length")
                if isinstance(ml, int) and ml >= 0:
                    bytes_used += ml

    # Log the call as succeeded (observable dynamics)
    _log_call(fetch_requests_rows, key_row.get("id"), "succeeded")
    _save("fetch_requests.json", fetch_requests_rows)

    latency_ms = int((time.time() - t0) * 1000)

    return {
        "caller": {
            "api_key_id": key_row.get("id"),
            "label": key_row.get("label"),
            "status": key_row.get("status"),
            "quota_requests_per_day": key_row.get("quota_requests_per_day"),
            "quota_bytes_per_day": key_row.get("quota_bytes_per_day"),
            "created_at": key_row.get("created_at"),
            "updated_at": key_row.get("updated_at"),
            "revoked_at": key_row.get("revoked_at"),
            "usage_today": {
                "date_utc": day_start.strftime("%Y-%m-%d"),
                "requests_used": requests_used,
                "bytes_used_best_effort": bytes_used,
            },
        },
        "meta": {
            "latency_ms": latency_ms,
            "timestamp": now,
        },
    }
